{"file_path":"src/output.js","content":"function cmp(a, b) {
  const x = Array.from(a, (c) => c.codePointAt(0))
  const y = Array.from(b, (c) => c.codePointAt(0))
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) if (x[i] !== y[i]) return x[i] - y[i]
  return x.length - y.length
}

const sortedKeys = (t) => [...t.m.keys()].sort(cmp)

function ser(node, ind) {
  const pad = '  '.repeat(ind + 1)
  const end = '  '.repeat(ind)
  if (node.k === 'table') {
    const ks = sortedKeys(node)
    if (!ks.length) return '{}'
    return '{\n' + ks.map((k) => `${pad}${JSON.stringify(k)}: ${ser(node.m.get(k), ind + 1)}`).join(',\n') + '\n' + end + '}'
  }
  if (node.k === 'array') {
    if (!node.items.length) return '[]'
    return '[\n' + node.items.map((n) => pad + ser(n, ind + 1)).join(',\n') + '\n' + end + ']'
  }
  return JSON.stringify(node.v)
}

export const toJson = (root) => ser(root, 0) + '\n'

export function toKeys(root) {
  const out = []
  const walk = (node, path) => {
    if (node.k === 'table') {
      for (const k of sortedKeys(node)) {
        const p = path === null ? k : `${path}.${k}`
        out.push(`${p} ${node.m.get(k).k}`)
        walk(node.m.get(k), p)
      }
    } else if (node.k === 'array') {
      node.items.forEach((it, i) => {
        const p = `${path}[${i}]`
        out.push(`${p} ${it.k}`)
        walk(it, p)
      })
    }
  }
  walk(root, null)
  return out.map((l) => l + '\n').join('')
}
"}

