{"file_path":"src/parse.js","content":"const fail = (msg) => {
  const e = new Error(msg)
  e.configError = true
  return e
}

const newTable = () => ({ k: 'table', m: new Map(), hdr: false })
const isWs = (c) => c === ' ' || c === '\t'
const isBare = (c) => c !== undefined && /[A-Za-z0-9_-]/.test(c)

function descend(tbl, names, base) {
  const path = [...base]
  for (const n of names) {
    path.push(n)
    let c = tbl.m.get(n)
    if (c === undefined) {
      c = newTable()
      tbl.m.set(n, c)
    }
    if (c.k === 'table') tbl = c
    else if (c.k === 'array' && c.aot) tbl = c.items[c.items.length - 1]
    else throw fail(`${path.join('.')} is not a table`)
  }
  return tbl
}

function assign(tbl, names, base, value) {
  const t = descend(tbl, names.slice(0, -1), base)
  const last = names[names.length - 1]
  if (t.m.has(last)) throw fail(`key ${[...base, ...names].join('.')} is defined twice`)
  t.m.set(last, value)
}

class LineParser {
  constructor(s) {
    this.s = s
    this.i = 0
  }
  skipWs() {
    while (isWs(this.s[this.i])) this.i++
  }
  atEnd() {
    const c = this.s[this.i]
    return c === undefined || c === '#' || c === ';'
  }
  basicString() {
    const s = this.s
    this.i++
    let out = ''
    for (;;) {
      const c = s[this.i]
      if (c === undefined) throw fail('unterminated string')
      if (c === '"') {
        this.i++
        return out
      }
      if (c === '\\') {
        const e = s[this.i + 1]
        if (e === undefined) throw fail('unterminated string')
        const map = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
        if (Object.hasOwn(map, e)) {
          out += map[e]
          this.i += 2
        } else if (e === 'u') {
          const h = s.slice(this.i + 2, this.i + 6)
          if (!/^[0-9A-Fa-f]{4}$/.test(h)) throw fail('invalid escape \\u')
          out += String.fromCharCode(parseInt(h, 16))
          this.i += 6
        } else {
          const cp = String.fromCodePoint(s.codePointAt(this.i + 1))
          throw fail(`invalid escape \\${cp}`)
        }
      } else {
        out += c
        this.i++
      }
    }
  }
  literalString() {
    const j = this.s.indexOf("'", this.i + 1)
    if (j < 0) throw fail('unterminated string')
    const v = this.s.slice(this.i + 1, j)
    this.i = j + 1
    return v
  }
  name() {
    const c = this.s[this.i]
    if (c === '"') return this.basicString()
    if (c === "'") return this.literalString()
    const st = this.i
    while (isBare(this.s[this.i])) this.i++
    if (this.i === st) throw fail('expected a name')
    return this.s.slice(st, this.i)
  }
  dotted() {
    const names = [this.name()]
    this.skipWs()
    while (this.s[this.i] === '.') {
      this.i++
      this.skipWs()
      names.push(this.name())
      this.skipWs()
    }
    return names
  }
  value(base) {
    const s = this.s
    this.skipWs()
    const c = s[this.i]
    if (c === undefined || c === '#' || c === ';' || c === ',' || c === ']' || c === '}') throw fail('expected a value')
    if (c === '"') return { k: 'string', v: this.basicString() }
    if (c === "'") return { k: 'string', v: this.literalString() }
    if (c === '[') return this.array(base)
    if (c === '{') return this.inline(base)
    const st = this.i
    while (this.i < s.length && !isWs(s[this.i]) && !',]};'.includes(s[this.i])) this.i++
    const t = s.slice(st, this.i)
    if (t === 'true') return { k: 'boolean', v: true }
    if (t === 'false') return { k: 'boolean', v: false }
    const digits = '[0-9]+(?:_[0-9]+)*'
    if (new RegExp(`^[+-]?${digits}$`).test(t)) return { k: 'integer', v: Number(t.replace(/_/g, '')) }
    if (new RegExp(`^[+-]?${digits}(?:\\.${digits})?(?:[eE][+-]?${digits})?$`).test(t)) {
      return { k: 'float', v: Number(t.replace(/_/g, '')) }
    }
    throw fail(`invalid value ${t}`)
  }
  array(base) {
    this.i++
    const arr = { k: 'array', items: [], aot: false }
    for (;;) {
      this.skipWs()
      if (this.atEnd()) throw fail('unterminated array')
      if (this.s[this.i] === ']') {
        this.i++
        return arr
      }
      arr.items.push(this.value(base))
      this.skipWs()
      const c = this.s[this.i]
      if (c === ',') this.i++
      else if (c === ']') {
        this.i++
        return arr
      } else throw fail('unterminated array')
    }
  }
  inline(base) {
    this.i++
    const tbl = newTable()
    this.skipWs()
    if (this.s[this.i] === '}') {
      this.i++
      return tbl
    }
    for (;;) {
      this.skipWs()
      if (this.atEnd()) throw fail('unterminated inline table')
      const names = this.dotted()
      if (this.s[this.i] !== '=') {
        if (this.atEnd()) throw fail('unterminated inline table')
        throw fail('expected = in an inline table')
      }
      this.i++
      const v = this.value([...base, ...names])
      assign(tbl, names, base, v)
      this.skipWs()
      const c = this.s[this.i]
      if (c === ',') this.i++
      else if (c === '}') {
        this.i++
        return tbl
      } else throw fail('unterminated inline table')
    }
  }
}

export function parseDocument(input) {
  const lines = input.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const root = newTable()
  let cur = root
  let curPath = []
  for (let n = 0; n < lines.length; n++) {
    try {
      const p = new LineParser(lines[n])
      p.skipWs()
      const c = p.s[p.i]
      if (c === undefined || c === '#' || c === ';') continue
      if (c === '[') {
        const aot = p.s[p.i + 1] === '['
        p.i += aot ? 2 : 1
        p.skipWs()
        if (p.atEnd()) throw fail('unterminated table header')
        const names = p.dotted()
        const close = aot ? ']]' : ']'
        if (p.s.slice(p.i, p.i + close.length) !== close) throw fail('unterminated table header')
        p.i += close.length
        p.skipWs()
        if (!p.atEnd()) throw fail('trailing text after a table header')
        const parent = descend(root, names.slice(0, -1), [])
        const last = names[names.length - 1]
        const full = names.join('.')
        const ex = parent.m.get(last)
        if (aot) {
          const t = newTable()
          if (ex === undefined) parent.m.set(last, { k: 'array', items: [t], aot: true })
          else if (ex.k === 'array' && ex.aot) ex.items.push(t)
          else throw fail(`${full} is not an array of tables`)
          cur = t
        } else {
          if (ex === undefined) {
            const t = newTable()
            t.hdr = true
            parent.m.set(last, t)
            cur = t
          } else if (ex.k === 'table') {
            if (ex.hdr) throw fail(`table ${full} is defined twice`)
            ex.hdr = true
            cur = ex
          } else throw fail(`${full} is not a table`)
        }
        curPath = names
        continue
      }
      const names = p.dotted()
      if (p.s[p.i] !== '=') throw fail('expected key = value')
      p.i++
      const v = p.value([...curPath, ...names])
      p.skipWs()
      if (!p.atEnd()) throw fail('trailing text after a value')
      assign(cur, names, curPath, v)
    } catch (e) {
      if (e && e.configError) e.message = `line ${n + 1}: ${e.message}`
      throw e
    }
  }
  return root
}
"}

