import { toJson, toKeys } from './output.js'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'json' && mode !== 'keys') {
  process.stderr.write('error: usage: cli.js json|keys\n')
  process.exitCode = 2
} else {
  const input = readFileSync(0, 'utf8')
  try {
    const root = parseDocument(input)
    process.stdout.write(mode === 'json' ? toJson(root) : toKeys(root))
  } catch (e) {
    if (e && e.configError) {
      process.stderr.write(`error: ${e.message}\n`)
      process.exitCode = 2
    } else throw e
  }
}
"}

